FUNCTION_BLOCK FB_SubseaMethaneHydrate_ChokeDepressurization
(*
 ====================================================================================================
 LUMINA CYBER-PHYSICAL AUTOMATION ARCHITECTURE - SUBSEA OIL & GAS CONTROL SYSTEMS GROUP
 V7 ULTRA-RIGOROUS SYNTHETIC CORPUS BENCHMARK: SUBSEA METHANE HYDRATE WELLHEAD CONTROLLER
 IEC 61131-3 COMPLIANT FUNCTION BLOCK ARCHITECTURE
 ----------------------------------------------------------------------------------------------------
 DOMAIN: Subsea Deep-Ocean Methane Hydrate Production via Thermodynamic Depressurization Combined with
         Seafloor Trace Heating, 2oo3 TMR Primary Sensor Analytics, State-Space Multivariable Model
         Predictive Control (MPC), and Solid Particle Centrifugal Desanding Cyclone Choke Regulation.
 ----------------------------------------------------------------------------------------------------
 DESIGN CRITERIA & ENGINEERING SPECIFICATIONS:
  - Deep-ocean hydrostatic wellhead environment: Water depth ~1200m - 2000m (Ambient P ~120 - 200 bar, T ~3.5 deg C)
  - Clathrate Hydrate Phase Dissociation: In-situ gas hydrate dissociation controlled by pressure draw-down
    below Sloan-Kamath methane hydrate equilibrium pressure boundary:
      ln(P_eq) = 38.980 - (8533.8 / (T_K)) [P_eq in bar abs, T_K in Kelvin]
  - Joule-Thomson Cryogenic Chilling Suppression: Expansion across choke causes severe dT/dP chilling
    down to -15 deg C without active thermodynamic hydrate inhibitor (MEG) or electric trace heating.
  - Seafloor Desanding Hydrocyclone Separation:
      Centrifugal field removes formation sand particles (d50 > 25 um) to prevent erosion of topside risers.
      API RP 14E erosion velocity threshold envelope dynamically enforced.
  - Sensor Architecture: Dual-triple modular redundancy (2oo3 TMR) on wellhead pressure (PT_01A/B/C)
    and temperature (TT_01A/B/C) with bumpless graceful degradation down to 1oo2, 1oo1, and Safe Hold.
  - Control Strategy: State-space dynamic model with receding horizon quadratic cost optimization
    approximating constrained multivariable Model Predictive Control (MPC) on Delta-P and Delta-T.
 ====================================================================================================
*)

VAR_INPUT
    bEnableSubseaSubsystem          : BOOL;     (* Master supervisory execution permit *)
    bSafetyRelayEsdTripped          : BOOL;     (* Active-LOW SIL-3 Emergency Shutdown relay loop [healthy=TRUE, trip=FALSE] *)
    bManualAcknowledgeFault         : BOOL;     (* Operator alarm clear and latch reset push-button *)

    (* --- 2oo3 Triple Modular Redundant Wellhead Pressure Sensors --- *)
    rPT_Wellhead_ChA                : REAL;     (* Pressure transducer channel A [bar] *)
    rPT_Wellhead_ChB                : REAL;     (* Pressure transducer channel B [bar] *)
    rPT_Wellhead_ChC                : REAL;     (* Pressure transducer channel C [bar] *)

    (* --- 2oo3 Triple Modular Redundant Wellhead Temperature Sensors --- *)
    rTT_Wellhead_ChA                : REAL;     (* Temperature transmitter channel A [deg C] *)
    rTT_Wellhead_ChB                : REAL;     (* Temperature transmitter channel B [deg C] *)
    rTT_Wellhead_ChC                : REAL;     (* Temperature transmitter channel C [deg C] *)

    (* --- Process Physical Measurements --- *)
    rMassFlow_ReservoirTotal        : REAL;     (* Multiphase wellbore mass production rate [kg/s] *)
    rGasVolumeFraction_GVF          : REAL;     (* Gas-to-liquid volumetric ratio at wellhead [0.0 - 1.0] *)
    rSandConcentration_Inlet        : REAL;     (* Acoustic / sand probe inlet solid loading [ppm wt] *)
    rSandMeanGrainSize_d50          : REAL;     (* Ultrasonic particle distribution median diameter [um] *)
    rDP_Hydrocyclone                : REAL;     (* Differential pressure across desanding cyclone body [bar] *)
    rP_RiserBackpressure            : REAL;     (* Downstream production riser export manifold pressure [bar] *)
    rSeabedAmbientTemp              : REAL;     (* Ambient benthic seawater boundary layer temperature [deg C] *)
    rMEG_ManifoldPressure           : REAL;     (* Monoethylene glycol supply umbilical manifold pressure [bar] *)
    rAcousticErosionProbeRate       : REAL;     (* Ultrasonic structural wear sensor thinning rate [um/day] *)

    (* --- Target Operational Setpoints --- *)
    rSetpoint_DepressurizationTarget: REAL;     (* Target bottom-hole dissociation pressure [bar] *)
    rSetpoint_MinHydrateSubcoolMargin: REAL;    (* Safety subcooling temperature buffer above phase curve [deg C] *)
    rTarget_MaxErosionRateLimit     : REAL;     (* Maximum allowable metal wear limit [um/day] *)
    rCycleTime_DeltaT_Sec           : REAL := 0.1; (* Cyclic scan execution step interval [s] *)
END_VAR

VAR_OUTPUT
    (* --- Primary Actuator Manipulated Variables --- *)
    rChokePosition_Cmd              : REAL;     (* Subsea hydraulic stepping choke valve position setpoint [0.0 - 100.0 %] *)
    rMEG_DosingRate_Cmd             : REAL;     (* Thermodynamic hydrate inhibitor dosing injection flow [kg/s] *)
    rSeabedHeaterDuty_Cmd           : REAL;     (* Subsea benthic electric heating jacket duty cycle [0.0 - 100.0 %] *)
    rCycloneUnderflowValve_Cmd      : REAL;     (* Desander sand accumulator intermittent blowdown valve [0.0 - 100.0 %] *)

    (* --- Supervisory Telemetry & Diagnostic Status Words --- *)
    wHydrateSafetyStatusWord        : WORD;     (* Hexadecimal status word (TMR state, operational state machine) *)
    dwActiveAlarmMask               : DWORD;    (* Packed 32-bit alarm diagnostic tree bitmask *)
    rVoted_WellheadPressure_bar     : REAL;     (* TMR 2oo3 validated wellhead pressure [bar] *)
    rVoted_WellheadTemp_degC        : REAL;     (* TMR 2oo3 validated wellhead temperature [deg C] *)
    rEquilibriumHydrateTemp_degC    : REAL;     (* Sloan-Kamath calculated hydrate dissociation boundary [deg C] *)
    rEstimatedSubcoolingMargin_degC : REAL;     (* Thermodynamic safety margin (T_voted - T_eq) [deg C] *)
    rCycloneSeparationEfficiency    : REAL;     (* Calculated centrifugal sand removal ratio [0.0 - 1.0] *)
    rAccumulatedChokeErosion_um     : REAL;     (* Integrated cumulative choke cage sacrificial wear [um] *)
    bProductionRegimeActive         : BOOL;     (* True when in stable gas hydrate dissociation flow *)
    bSafeParkCompleted              : BOOL;     (* True when subsea tree is safely locked and inhibited *)
    iActiveOperatingState           : INT;      (* Active CASE state machine numeric identifier *)
END_VAR

VAR
    (* ========================================================================= *)
    (* INTERNAL ARCHITECTURAL STATE VARIABLES & TIMERS                           *)
    (* ========================================================================= *)
    iStateMachine                   : INT := 0; (* Internal execution state *)
    tStepTimer                      : TON;      (* State transition dwell and ramp sequencer timer *)
    tCycloneFlushTimer              : TON;      (* Periodic sand accumulator flush cycle timer *)
    tWatchdogPulseTimer             : TON;      (* Umbilical heartbeat telemetry sanity timer *)

    (* --- 2oo3 TMR Voting Logic Internal Registers --- *)
    bPT_ChA_Healthy                 : BOOL;
    bPT_ChB_Healthy                 : BOOL;
    bPT_ChC_Healthy                 : BOOL;
    iPT_ValidCount                  : INT;
    rPT_DiffAB                      : REAL;
    rPT_DiffBC                      : REAL;
    rPT_DiffAC                      : REAL;

    bTT_ChA_Healthy                 : BOOL;
    bTT_ChB_Healthy                 : BOOL;
    bTT_ChC_Healthy                 : BOOL;
    iTT_ValidCount                  : INT;
    rTT_DiffAB                      : REAL;
    rTT_DiffBC                      : REAL;
    rTT_DiffAC                      : REAL;

    (* --- State-Space Discrete Model Matrices (3x3 Plant: x = [P_dev, T_dev, Sand_accum]^T) --- *)
    (* Plant Continuous Representation discretized at Ts = 0.1s via Bilinear Tustin Transformation *)
    (* A matrix coefficients: State cross-coupling *)
    rA_11 : REAL := 0.9820;  rA_12 : REAL := 0.0150;  rA_13 : REAL := 0.0000;
    rA_21 : REAL :=-0.0320;  rA_22 : REAL := 0.9650;  rA_23 : REAL := 0.0000;
    rA_31 : REAL := 0.0045;  rA_32 : REAL := 0.0000;  rA_33 : REAL := 0.9910;

    (* B matrix coefficients: Input authority (u1 = Delta Choke %, u2 = Delta Heater %) *)
    rB_11 : REAL :=-0.1420;  rB_12 : REAL := 0.0020;
    rB_21 : REAL :=-0.0880;  rB_22 : REAL := 0.0450;
    rB_31 : REAL := 0.0650;  rB_32 : REAL := 0.0000;

    (* State vector estimates: x_k *)
    rState_PressDeviation_bar       : REAL := 0.0;
    rState_TempDeviation_degC       : REAL := 0.0;
    rState_SandAccumulation_kg      : REAL := 0.0;

    (* State Prediction buffer: x_pred *)
    rPred_Press_bar                 : REAL := 0.0;
    rPred_Temp_degC                 : REAL := 0.0;
    rPred_Sand_kg                   : REAL := 0.0;

    (* MPC Quadratic Cost Function Weighting Factors *)
    rQ_PressurePenalty              : REAL := 12.5; (* State error weight on target wellhead pressure *)
    rQ_TemperaturePenalty           : REAL := 45.0; (* Severe penalty on subcooling violation *)
    rQ_SandBedPenalty               : REAL := 2.5;  (* Hydrocyclone bed over-fill penalty *)
    rR_ChokeRatePenalty             : REAL := 8.0;  (* Choke mechanical wear and water-hammer penalty *)
    rR_HeaterRatePenalty            : REAL := 1.5;  (* Subsea umbilical power consumption penalty *)

    (* MPC Gradient Descent Solvers & Active Set Control Variables *)
    rGrad_u1                        : REAL := 0.0;
    rGrad_u2                        : REAL := 0.0;
    rOpt_DeltaChoke                 : REAL := 0.0;
    rOpt_DeltaHeater                : REAL := 0.0;
    rChokePosition_Internal         : REAL := 0.0;
    rHeaterDuty_Internal            : REAL := 0.0;

    (* Desanding Cyclone Mathematical Modeling *)
    rCyclone_dCrit_CutSize_um       : REAL := 18.5; (* Nominal d50 cut diameter for hydrocyclone geometry *)
    rCyclone_FluidVelocity          : REAL := 0.0;
    rMixtureDensity_kg_m3           : REAL := 820.0;
    rAPI_MaxAllowableVelocity       : REAL := 12.0; (* API RP 14E allowable erosive velocity limit [m/s] *)
    rCurrentSandInventory_kg        : REAL := 0.0;

    (* Choke Valve Flow Sizing & Joule-Thomson Cryogenic Calculations *)
    rJouleThomsonCoeff_degC_bar     : REAL := 1.62; (* Methane Joule-Thomson expansion cooling rate [deg C / bar] *)
    rCalculatedJTCooling_degC       : REAL := 0.0;
    rPresumedChokeDownstreamTemp    : REAL := 0.0;

    (* Safety Logic, Ramp Slopes & Hysteresis *)
    rChokeMaxRampRate_pct_per_sec   : REAL := 0.50; (* Strict physical choke travel limit: 0.5% per sec *)
    rDepressurizationRampRate_bar_s : REAL := 0.08; (* Controlled reservoir draw-down rate: 0.08 bar/s *)
    rCurrentTargetPressure_bar      : REAL := 150.0;
    rEmergencyInhibitorDoseRate     : REAL := 4.50; (* Fixed emergency MEG rate [kg/s] during lockup *)
    rChokeErosionModelGain          : REAL := 0.000012; (* Sand erosive coefficient *)

    (* Temporary math computation scratch registers *)
    rTemp_Kelvin                    : REAL;
    rLnArg                          : REAL;
    rExpArg                         : REAL;
    rDistSquaredAB                  : REAL;
    rDistSquaredBC                  : REAL;
    rDistSquaredCA                  : REAL;
    rVotedPT_Raw                    : REAL;
    rVotedTT_Raw                    : REAL;
END_VAR

(*
 ====================================================================================================
 SECTION 1: SENSOR VALIDATION, 2oo3 TMR VOTING & BUMPLESS DEGRADATION MATRIX
 ====================================================================================================
*)

(* Initialize sensor healthy flags and validation counters *)
iPT_ValidCount := 0;
bPT_ChA_Healthy := (rPT_Wellhead_ChA >= 5.0) AND (rPT_Wellhead_ChA <= 350.0);
bPT_ChB_Healthy := (rPT_Wellhead_ChB >= 5.0) AND (rPT_Wellhead_ChB <= 350.0);
bPT_ChC_Healthy := (rPT_Wellhead_ChC >= 5.0) AND (rPT_Wellhead_ChC <= 350.0);

IF bPT_ChA_Healthy THEN iPT_ValidCount := iPT_ValidCount + 1; END_IF;
IF bPT_ChB_Healthy THEN iPT_ValidCount := iPT_ValidCount + 1; END_IF;
IF bPT_ChC_Healthy THEN iPT_ValidCount := iPT_ValidCount + 1; END_IF;

(* Inter-channel delta divergence checks (TMR Discrepancy threshold = 6.5 bar) *)
rPT_DiffAB := ABS(rPT_Wellhead_ChA - rPT_Wellhead_ChB);
rPT_DiffBC := ABS(rPT_Wellhead_ChB - rPT_Wellhead_ChC);
rPT_DiffAC := ABS(rPT_Wellhead_ChA - rPT_Wellhead_ChC);

IF (iPT_ValidCount = 3) THEN
    (* Full 2oo3 Voting: Mid-value selection algorithm *)
    IF ((rPT_Wellhead_ChA >= rPT_Wellhead_ChB) AND (rPT_Wellhead_ChA <= rPT_Wellhead_ChC)) OR
       ((rPT_Wellhead_ChA <= rPT_Wellhead_ChB) AND (rPT_Wellhead_ChA >= rPT_Wellhead_ChC)) THEN
        rVotedPT_Raw := rPT_Wellhead_ChA;
    ELSIF ((rPT_Wellhead_ChB >= rPT_Wellhead_ChA) AND (rPT_Wellhead_ChB <= rPT_Wellhead_ChC)) OR
          ((rPT_Wellhead_ChB <= rPT_Wellhead_ChA) AND (rPT_Wellhead_ChB >= rPT_Wellhead_ChC)) THEN
        rVotedPT_Raw := rPT_Wellhead_ChB;
    ELSE
        rVotedPT_Raw := rPT_Wellhead_ChC;
    END_IF;

    (* Latch channel discrepancy alarm if drift exceeds allowable limit *)
    IF (rPT_DiffAB > 6.5) OR (rPT_DiffBC > 6.5) OR (rPT_DiffAC > 6.5) THEN
        dwActiveAlarmMask.0 := TRUE; (* Alarm Bit 0: PT TMR Inter-channel Discrepancy *)
    ELSE
        IF bManualAcknowledgeFault THEN dwActiveAlarmMask.0 := FALSE; END_IF;
    END_IF;

ELSIF (iPT_ValidCount = 2) THEN
    (* Degraded 1oo2 Voting: Mean of two remaining healthy channels *)
    IF bPT_ChA_Healthy AND bPT_ChB_Healthy THEN
        rVotedPT_Raw := (rPT_Wellhead_ChA + rPT_Wellhead_ChB) * 0.5;
    ELSIF bPT_ChB_Healthy AND bPT_ChC_Healthy THEN
        rVotedPT_Raw := (rPT_Wellhead_ChB + rPT_Wellhead_ChC) * 0.5;
    ELSE
        rVotedPT_Raw := (rPT_Wellhead_ChA + rPT_Wellhead_ChC) * 0.5;
    END_IF;
    dwActiveAlarmMask.1 := TRUE; (* Alarm Bit 1: PT Degraded to 1oo2 operation *)

ELSIF (iPT_ValidCount = 1) THEN
    (* Degraded Simplex 1oo1: Critical single-point of failure operation *)
    IF bPT_ChA_Healthy THEN
        rVotedPT_Raw := rPT_Wellhead_ChA;
    ELSIF bPT_ChB_Healthy THEN
        rVotedPT_Raw := rPT_Wellhead_ChB;
    ELSE
        rVotedPT_Raw := rPT_Wellhead_ChC;
    END_IF;
    dwActiveAlarmMask.2 := TRUE; (* Alarm Bit 2: PT Degraded to Simplex 1oo1 *)

ELSE
    (* Total Sensor Failure: Fail-safe fallback to export riser backpressure + hydrostatic estimate *)
    rVotedPT_Raw := rP_RiserBackpressure + 25.0;
    dwActiveAlarmMask.3 := TRUE; (* Alarm Bit 3: PT Total Loss of Signal Trip *)
END_IF;

rVoted_WellheadPressure_bar := rVotedPT_Raw;

(* Temperature Transmitters 2oo3 TMR Processing *)
iTT_ValidCount := 0;
bTT_ChA_Healthy := (rTT_Wellhead_ChA >= -20.0) AND (rTT_Wellhead_ChA <= 80.0);
bTT_ChB_Healthy := (rTT_Wellhead_ChB >= -20.0) AND (rTT_Wellhead_ChB <= 80.0);
bTT_ChC_Healthy := (rTT_Wellhead_ChC >= -20.0) AND (rTT_Wellhead_ChC <= 80.0);

IF bTT_ChA_Healthy THEN iTT_ValidCount := iTT_ValidCount + 1; END_IF;
IF bTT_ChB_Healthy THEN iTT_ValidCount := iTT_ValidCount + 1; END_IF;
IF bTT_ChC_Healthy THEN iTT_ValidCount := iTT_ValidCount + 1; END_IF;

rTT_DiffAB := ABS(rTT_Wellhead_ChA - rTT_Wellhead_ChB);
rTT_DiffBC := ABS(rTT_Wellhead_ChB - rTT_Wellhead_ChC);
rTT_DiffAC := ABS(rTT_Wellhead_ChA - rTT_Wellhead_ChC);

IF (iTT_ValidCount = 3) THEN
    (* Mid-value selection *)
    IF ((rTT_Wellhead_ChA >= rTT_Wellhead_ChB) AND (rTT_Wellhead_ChA <= rTT_Wellhead_ChC)) OR
       ((rTT_Wellhead_ChA <= rTT_Wellhead_ChB) AND (rTT_Wellhead_ChA >= rTT_Wellhead_ChC)) THEN
        rVotedTT_Raw := rTT_Wellhead_ChA;
    ELSIF ((rTT_Wellhead_ChB >= rTT_Wellhead_ChA) AND (rTT_Wellhead_ChB <= rTT_Wellhead_ChC)) OR
          ((rTT_Wellhead_ChB <= rTT_Wellhead_ChA) AND (rTT_Wellhead_ChB >= rTT_Wellhead_ChC)) THEN
        rVotedTT_Raw := rTT_Wellhead_ChB;
    ELSE
        rVotedTT_Raw := rTT_Wellhead_ChC;
    END_IF;

    IF (rTT_DiffAB > 2.5) OR (rTT_DiffBC > 2.5) OR (rTT_DiffAC > 2.5) THEN
        dwActiveAlarmMask.4 := TRUE; (* Alarm Bit 4: TT TMR Inter-channel Discrepancy *)
    ELSE
        IF bManualAcknowledgeFault THEN dwActiveAlarmMask.4 := FALSE; END_IF;
    END_IF;

ELSIF (iTT_ValidCount = 2) THEN
    IF bTT_ChA_Healthy AND bTT_ChB_Healthy THEN
        rVotedTT_Raw := (rTT_Wellhead_ChA + rTT_Wellhead_ChB) * 0.5;
    ELSIF bTT_ChB_Healthy AND bTT_ChC_Healthy THEN
        rVotedTT_Raw := (rTT_Wellhead_ChB + rTT_Wellhead_ChC) * 0.5;
    ELSE
        rVotedTT_Raw := (rTT_Wellhead_ChA + rTT_Wellhead_ChC) * 0.5;
    END_IF;
    dwActiveAlarmMask.5 := TRUE; (* Alarm Bit 5: TT Degraded to 1oo2 *)

ELSIF (iTT_ValidCount = 1) THEN
    IF bTT_ChA_Healthy THEN rVotedTT_Raw := rTT_Wellhead_ChA;
    ELSIF bTT_ChB_Healthy THEN rVotedTT_Raw := rTT_Wellhead_ChB;
    ELSE rVotedTT_Raw := rTT_Wellhead_ChC;
    END_IF;
    dwActiveAlarmMask.6 := TRUE; (* Alarm Bit 6: TT Degraded to Simplex 1oo1 *)

ELSE
    rVotedTT_Raw := rSeabedAmbientTemp;
    dwActiveAlarmMask.7 := TRUE; (* Alarm Bit 7: TT Total Sensor Loss *)
END_IF;

rVoted_WellheadTemp_degC := rVotedTT_Raw;

(*
 ====================================================================================================
 SECTION 2: THERMODYNAMIC CLATHRATE HYDRATE PHASE EQUILIBRIUM ENGINE
 ====================================================================================================
*)

(* Sloan-Kamath Equation for Pure Methane Hydrate (Structure I) Dissociation:
   ln(P_eq) = 38.980 - 8533.8 / T_K
   Solving for Equilibrium Dissociation Temperature at given measured wellhead pressure P:
   T_K_eq = 8533.8 / (38.980 - ln(P_bar_abs))
*)
IF (rVoted_WellheadPressure_bar > 1.0) THEN
    rLnArg := LN(rVoted_WellheadPressure_bar);
    IF (rLnArg < 38.90) THEN
        rEquilibriumHydrateTemp_degC := (8533.8 / (38.980 - rLnArg)) - 273.15;
    ELSE
        rEquilibriumHydrateTemp_degC := 40.0; (* Upper thermodynamic bound *)
    END_IF;
ELSE
    rEquilibriumHydrateTemp_degC := -15.0;
END_IF;

(* Subcooling Margin: positive values indicate safe warm zone, negative indicates hydrate formation *)
rEstimatedSubcoolingMargin_degC := rVoted_WellheadTemp_degC - rEquilibriumHydrateTemp_degC;

(* Joule-Thomson Cryogenic Chilling Calculation across the choke cage *)
IF (rVoted_WellheadPressure_bar > rP_RiserBackpressure) THEN
    rCalculatedJTCooling_degC := rJouleThomsonCoeff_degC_bar * (rVoted_WellheadPressure_bar - rP_RiserBackpressure);
ELSE
    rCalculatedJTCooling_degC := 0.0;
END_IF;
rPresumedChokeDownstreamTemp := rVoted_WellheadTemp_degC - rCalculatedJTCooling_degC;

(* Hydrate Reformation Alarm Thresholds *)
IF (rEstimatedSubcoolingMargin_degC < rSetpoint_MinHydrateSubcoolMargin) THEN
    dwActiveAlarmMask.8 := TRUE; (* Alarm Bit 8: Hydrate Subcooling Margin Low *)
ELSE
    IF bManualAcknowledgeFault THEN dwActiveAlarmMask.8 := FALSE; END_IF;
END_IF;

IF (rPresumedChokeDownstreamTemp < (rEquilibriumHydrateTemp_degC + 1.0)) THEN
    dwActiveAlarmMask.9 := TRUE; (* Alarm Bit 9: Choke Core Downstream Cryogenic Freeze Threat *)
ELSE
    IF bManualAcknowledgeFault THEN dwActiveAlarmMask.9 := FALSE; END_IF;
END_IF;

(*
 ====================================================================================================
 SECTION 3: HYDROCYCLONE SAND SEPARATION & EROSION DYNAMICS
 ====================================================================================================
*)

(* Desander centrifugal d50 cut separation efficiency via Rosin-Rammler exponential function *)
IF (rSandMeanGrainSize_d50 > 1.0) AND (rCyclone_dCrit_CutSize_um > 1.0) THEN
    rExpArg := -1.0 * EXPT((rCyclone_dCrit_CutSize_um / rSandMeanGrainSize_d50), 1.8);
    IF (rExpArg < 0.0) AND (rExpArg > -20.0) THEN
        rCycloneSeparationEfficiency := 1.0 - EXP(rExpArg);
    ELSE
        rCycloneSeparationEfficiency := 0.99;
    END_IF;
ELSE
    rCycloneSeparationEfficiency := 0.50;
END_IF;

(* Mixture velocity inside cyclone inlet nozzle and API RP 14E erosion envelope *)
IF (rMassFlow_ReservoirTotal > 0.01) THEN
    rMixtureDensity_kg_m3 := (1.0 - rGasVolumeFraction_GVF) * 1025.0 + (rGasVolumeFraction_GVF * 95.0);
    rCyclone_FluidVelocity := rMassFlow_ReservoirTotal / (rMixtureDensity_kg_m3 * 0.00785); (* 100mm inlet throat *)
    rAPI_MaxAllowableVelocity := 125.0 / SQRT(rMixtureDensity_kg_m3);
ELSE
    rCyclone_FluidVelocity := 0.0;
END_IF;

IF (rCyclone_FluidVelocity > rAPI_MaxAllowableVelocity) THEN
    dwActiveAlarmMask.10 := TRUE; (* Alarm Bit 10: Choke Velocity Exceeds API 14E Erosive Limit *)
END_IF;

(* Solid Sand Inventory Accumulation Integrator inside desander collection boot *)
rCurrentSandInventory_kg := rCurrentSandInventory_kg + 
    (rMassFlow_ReservoirTotal * (rSandConcentration_Inlet / 1.0E6) * rCycloneSeparationEfficiency * rCycleTime_DeltaT_Sec);

(* Cumulative Structural Erosion Integration on Choke Cage [um] *)
rAccumulatedChokeErosion_um := rAccumulatedChokeErosion_um + 
    (rAcousticErosionProbeRate * (rCycleTime_DeltaT_Sec / 86400.0));

IF (rAccumulatedChokeErosion_um > 2500.0) THEN
    dwActiveAlarmMask.11 := TRUE; (* Alarm Bit 11: Severe Choke Mechanical Degradation / Wall Loss *)
END_IF;

(*
 ====================================================================================================
 SECTION 4: STATE-SPACE PREDICTIVE MODEL & QUADRATIC COST OPTIMIZATION (MPC KERNEL)
 ====================================================================================================
*)

(* Deviation state updates: Reference relative to operating baseline *)
rState_PressDeviation_bar  := rVoted_WellheadPressure_bar - rCurrentTargetPressure_bar;
rState_TempDeviation_degC  := rVoted_WellheadTemp_degC - (rEquilibriumHydrateTemp_degC + rSetpoint_MinHydrateSubcoolMargin);
rState_SandAccumulation_kg := rCurrentSandInventory_kg;

(* One-Step Ahead State Prediction via Discretized State-Space Plant Matrix: x[k+1] = A*x[k] + B*u[k] *)
rPred_Press_bar := (rA_11 * rState_PressDeviation_bar) + (rA_12 * rState_TempDeviation_degC) + (rA_13 * rState_SandAccumulation_kg)
                 + (rB_11 * rOpt_DeltaChoke) + (rB_12 * rOpt_DeltaHeater);

rPred_Temp_degC := (rA_21 * rState_PressDeviation_bar) + (rA_22 * rState_TempDeviation_degC) + (rA_23 * rState_SandAccumulation_kg)
                 + (rB_21 * rOpt_DeltaChoke) + (rB_22 * rOpt_DeltaHeater);

rPred_Sand_kg   := (rA_31 * rState_PressDeviation_bar) + (rA_32 * rState_TempDeviation_degC) + (rA_33 * rState_SandAccumulation_kg)
                 + (rB_31 * rOpt_DeltaChoke) + (rB_32 * rOpt_DeltaHeater);

(* Analytic Gradient of Quadratic Cost: J = 1/2*(x^T * Q * x + u^T * R * u)
   dJ/du1 = B_11 * Q_p * x_pred1 + B_21 * Q_t * x_pred2 + B_31 * Q_s * x_pred3 + R_choke * u1
   dJ/du2 = B_12 * Q_p * x_pred1 + B_22 * Q_t * x_pred2 + B_32 * Q_s * x_pred3 + R_heat * u2
*)
rGrad_u1 := (rB_11 * rQ_PressurePenalty * rPred_Press_bar) 
          + (rB_21 * rQ_TemperaturePenalty * rPred_Temp_degC) 
          + (rB_31 * rQ_SandBedPenalty * rPred_Sand_kg) 
          + (rR_ChokeRatePenalty * rOpt_DeltaChoke);

rGrad_u2 := (rB_12 * rQ_PressurePenalty * rPred_Press_bar) 
          + (rB_22 * rQ_TemperaturePenalty * rPred_Temp_degC) 
          + (rB_32 * rQ_SandBedPenalty * rPred_Sand_kg) 
          + (rR_HeaterRatePenalty * rOpt_DeltaHeater);

(* Projected Gradient Descent Step with Actuator Authority Clamping *)
rOpt_DeltaChoke  := -0.045 * rGrad_u1;
rOpt_DeltaHeater := -0.085 * rGrad_u2;

(* Clamp physical rate of change limits per execution cycle *)
IF (rOpt_DeltaChoke > (rChokeMaxRampRate_pct_per_sec * rCycleTime_DeltaT_Sec)) THEN
    rOpt_DeltaChoke := rChokeMaxRampRate_pct_per_sec * rCycleTime_DeltaT_Sec;
ELSIF (rOpt_DeltaChoke < (-1.0 * rChokeMaxRampRate_pct_per_sec * rCycleTime_DeltaT_Sec)) THEN
    rOpt_DeltaChoke := -1.0 * rChokeMaxRampRate_pct_per_sec * rCycleTime_DeltaT_Sec;
END_IF;

IF (rOpt_DeltaHeater > 1.0) THEN rOpt_DeltaHeater := 1.0;
ELSIF (rOpt_DeltaHeater < -1.0) THEN rOpt_DeltaHeater := -1.0;
END_IF;

(*
 ====================================================================================================
 SECTION 5: MULTI-STAGE FINITE STATE MACHINE (FSM) CONTROLLER
 ====================================================================================================
*)

(* Global Emergency Shutdown (ESD) Interlock Override *)
IF (NOT bSafetyRelayEsdTripped) OR (iPT_ValidCount = 0) THEN
    iStateMachine := 99; (* Trip directly into Safe Park Emergency Shutdown *)
END_IF;

CASE iStateMachine OF

    0: (* STATE 0: BOOTSTRAP & SUBSEA INTEGRITY PRE-CHECK *)
        bProductionRegimeActive := FALSE;
        bSafeParkCompleted      := FALSE;
        rChokePosition_Cmd      := 0.0;
        rMEG_DosingRate_Cmd     := 0.0;
        rSeabedHeaterDuty_Cmd   := 0.0;
        rCycloneUnderflowValve_Cmd := 0.0;
        rCurrentTargetPressure_bar := rVoted_WellheadPressure_bar;
        rChokePosition_Internal := 0.0;
        rHeaterDuty_Internal    := 0.0;

        tStepTimer(IN := FALSE, PT := T#5S);
        IF bEnableSubseaSubsystem AND bSafetyRelayEsdTripped AND (iPT_ValidCount >= 2) THEN
            iStateMachine := 10;
        END_IF;

    10: (* STATE 10: STANDBY PRESSURIZED COLD RESERVOIR STATE *)
        bProductionRegimeActive := FALSE;
        rChokePosition_Cmd      := 0.0;
        rMEG_DosingRate_Cmd     := 0.0;
        rSeabedHeaterDuty_Cmd   := 0.0;
        rCycloneUnderflowValve_Cmd := 0.0;

        (* Check if operator permits depressurization warm-up cycle *)
        IF bEnableSubseaSubsystem THEN
            iStateMachine := 20;
        END_IF;

    20: (* STATE 20: MEG INHIBITOR LINE PRIME & SEABED THERMAL PRE-HEATING *)
        bProductionRegimeActive := FALSE;
        rChokePosition_Cmd      := 0.0;
        (* Establish protective continuous thermodynamic inhibitor boundary layer *)
        rMEG_DosingRate_Cmd     := 1.25; (* Baseline protective injection rate [kg/s] *)
        rSeabedHeaterDuty_Cmd   := 85.0; (* Pre-warm choke manifold and sand cyclone body *)

        tStepTimer(IN := TRUE, PT := T#30S);
        (* Await thermal saturation of choke steel cage before initiation of flow *)
        IF tStepTimer.Q AND (rVoted_WellheadTemp_degC >= (rSeabedAmbientTemp + 8.0)) THEN
            tStepTimer(IN := FALSE);
            iStateMachine := 30;
        END_IF;

    30: (* STATE 30: CONTROLLED DEPRESSURIZATION RAMP DOWN TO DISSOCIATION THRESHOLD *)
        bProductionRegimeActive := FALSE;
        rSeabedHeaterDuty_Cmd   := 100.0;
        rMEG_DosingRate_Cmd     := 1.80;

        (* Step down target pressure at controlled rate (0.08 bar/s) to prevent uncontrolled sand burst *)
        IF (rCurrentTargetPressure_bar > rSetpoint_DepressurizationTarget) THEN
            rCurrentTargetPressure_bar := rCurrentTargetPressure_bar - (rDepressurizationRampRate_bar_s * rCycleTime_DeltaT_Sec);
        ELSE
            rCurrentTargetPressure_bar := rSetpoint_DepressurizationTarget;
        END_IF;

        (* Feedforward Choke Initial Opening Ramp *)
        IF (rChokePosition_Internal < 18.5) THEN
            rChokePosition_Internal := rChokePosition_Internal + (0.15 * rCycleTime_DeltaT_Sec);
        END_IF;
        rChokePosition_Cmd := rChokePosition_Internal;

        (* Transition to active MPC once pressure approaches dissociation boundary *)
        IF (rVoted_WellheadPressure_bar <= (rSetpoint_DepressurizationTarget + 4.0)) AND 
           (rMassFlow_ReservoirTotal > 1.5) THEN
            iStateMachine := 40;
        END_IF;

    40: (* STATE 40: CLOSED-LOOP MPC STEADY-STATE PRODUCTION & SAND REGULATION *)
        bProductionRegimeActive := TRUE;

        (* Apply MPC optimized control increments *)
        rChokePosition_Internal := rChokePosition_Internal + rOpt_DeltaChoke;
        rHeaterDuty_Internal    := rHeaterDuty_Internal + rOpt_DeltaHeater;

        (* Actuator output saturation limits *)
        IF (rChokePosition_Internal > 85.0) THEN rChokePosition_Internal := 85.0; END_IF;
        IF (rChokePosition_Internal < 2.0)  THEN rChokePosition_Internal := 2.0;  END_IF;
        IF (rHeaterDuty_Internal > 100.0)   THEN rHeaterDuty_Internal := 100.0;   END_IF;
        IF (rHeaterDuty_Internal < 0.0)     THEN rHeaterDuty_Internal := 0.0;     END_IF;

        rChokePosition_Cmd    := rChokePosition_Internal;
        rSeabedHeaterDuty_Cmd := rHeaterDuty_Internal;

        (* Proportional MEG dosing modulated by subcooling margin deficit *)
        IF (rEstimatedSubcoolingMargin_degC < 5.0) THEN
            rMEG_DosingRate_Cmd := 1.5 + (5.0 - rEstimatedSubcoolingMargin_degC) * 0.75;
        ELSE
            rMEG_DosingRate_Cmd := 0.65; (* Minimal baseline carrier flow *)
        END_IF;

        (* Autonomous Sand Accumulator Boot Blowdown Trigger *)
        IF (rCurrentSandInventory_kg >= 45.0) OR (rDP_Hydrocyclone > 3.8) THEN
            iStateMachine := 50;
        END_IF;

        (* Reformation anomaly protection *)
        IF (rEstimatedSubcoolingMargin_degC < 1.0) THEN
            iStateMachine := 60;
        END_IF;

    50: (* STATE 50: HYDROCYCLONE SAND BOOT HIGH-PRESSURE FLUSH CYCLE *)
        bProductionRegimeActive := TRUE;
        (* Maintain steady choke position during blowdown *)
        rChokePosition_Cmd := rChokePosition_Internal;
        (* Open underflow slurry discharge valve to seafloor sand disposal sump *)
        rCycloneUnderflowValve_Cmd := 100.0;

        tCycloneFlushTimer(IN := TRUE, PT := T#8S);
        IF tCycloneFlushTimer.Q THEN
            tCycloneFlushTimer(IN := FALSE);
            rCycloneUnderflowValve_Cmd := 0.0;
            rCurrentSandInventory_kg := 0.0; (* Reset sand accumulation estimator *)
            iStateMachine := 40;             (* Return to standard MPC production *)
        END_IF;

    60: (* STATE 60: CRITICAL HYDRATE REFORMATION INHIBITION & THERMAL SURGE *)
        bProductionRegimeActive := FALSE;
        (* Immediately close choke to minimum survival gap to reduce Joule-Thomson refrigeration *)
        IF (rChokePosition_Internal > 8.0) THEN
            rChokePosition_Internal := rChokePosition_Internal - (1.2 * rCycleTime_DeltaT_Sec);
        END_IF;
        rChokePosition_Cmd    := rChokePosition_Internal;
        rSeabedHeaterDuty_Cmd := 100.0;                 (* 100% full electrical thermal boost *)
        rMEG_DosingRate_Cmd   := rEmergencyInhibitorDoseRate; (* Emergency MEG flooding *)

        (* Once subcooling margin is restored above safe envelope, return to production *)
        IF (rEstimatedSubcoolingMargin_degC >= (rSetpoint_MinHydrateSubcoolMargin + 2.0)) THEN
            iStateMachine := 40;
        END_IF;

    90: (* STATE 90: GRACEFUL DEGRADED OPERATION (TMR FAILURE HOLD) *)
        bProductionRegimeActive := FALSE;
        (* Hold choke at fixed safe throttle, maintain defensive inhibitor injection *)
        rChokePosition_Cmd    := 12.0;
        rMEG_DosingRate_Cmd   := 3.0;
        rSeabedHeaterDuty_Cmd := 80.0;
        rCycloneUnderflowValve_Cmd := 0.0;

        IF bManualAcknowledgeFault AND (iPT_ValidCount >= 2) THEN
            iStateMachine := 10;
        END_IF;

    99: (* STATE 99: SIL-3 EMERGENCY SHUTDOWN SAFE PARK & BLOWDOWN ISOLATION *)
        bProductionRegimeActive    := FALSE;
        rChokePosition_Cmd         := 0.0;     (* Immediate spring-assisted choke closure *)
        rChokePosition_Internal    := 0.0;
        rSeabedHeaterDuty_Cmd      := 0.0;     (* De-energize subsea high-voltage power *)
        rCycloneUnderflowValve_Cmd := 0.0;     (* Isolate sand underflow path *)

        (* Flood wellhead cavity with MEG to avoid solid hydrate plug formation during cold soak *)
        IF (rMEG_ManifoldPressure > rVoted_WellheadPressure_bar) THEN
            rMEG_DosingRate_Cmd := 3.50; (* High pressure flushing dose *)
        ELSE
            rMEG_DosingRate_Cmd := 0.0;
        END_IF;

        bSafeParkCompleted := TRUE;

        IF bSafetyRelayEsdTripped AND bManualAcknowledgeFault AND (iPT_ValidCount >= 2) THEN
            bSafeParkCompleted := FALSE;
            iStateMachine := 0; (* Reset sequence *)
        END_IF;

END_CASE;

(*
