wHydrateSafetyStatusWord.0 := (iStateMachine = 40);
wHydrateSafetyStatusWord.1 := (iStateMachine = 50);
wHydrateSafetyStatusWord.2 := (iStateMachine = 60);
wHydrateSafetyStatusWord.3 := (iStateMachine = 99);
wHydrateSafetyStatusWord.4 := (iPT_ValidCount = 3);
wHydrateSafetyStatusWord.5 := (iTT_ValidCount = 3);
wHydrateSafetyStatusWord.6 := (rEstimatedSubcoolingMargin_degC >= rSetpoint_MinHydrateSubcoolMargin);
wHydrateSafetyStatusWord.7 := (rCycloneUnderflowValve_Cmd > 0.0);
wHydrateSafetyStatusWord.8 := NOT dwActiveAlarmMask.10;
wHydrateSafetyStatusWord.9 := (rMEG_ManifoldPressure > 50.0);
wHydrateSafetyStatusWord.10:= (rChokePosition_Cmd <= 0.05);
wHydrateSafetyStatusWord.11:= bSafeParkCompleted;

END_FUNCTION_BLOCK
